int runNativeActionCorpus(const std::string& folder,bool extended=false){
 using namespace Snatcher;std::vector<Scenario> all;std::string error;
 for(unsigned i=0;i<39;++i){char file[32];std::snprintf(file,sizeof(file),"/SP%02u.BIN",i);std::ifstream f((folder+file).c_str(),std::ios::binary);std::vector<uint8_t> data((std::istreambuf_iterator<char>(f)),std::istreambuf_iterator<char>());Scenario scene;if(!f&&!f.eof())return 2;if(!parseScenario(data.data(),data.size(),scene,error))return 2;all.push_back(scene);}
 EventScheduler events;SemanticTrace trace;NarrativeRuntime runtime(all,events,trace);unsigned count=0;
 for(unsigned i=0;i<39;++i)for(const Node& n:all[i].nodes){
  const Node *tuple=n.opcode==0x41?&n:n.opcode==0x42&&n.children.size()==1?all[i].at(n.children[0]):nullptr;if(!tuple||tuple->fields.empty())continue;unsigned subtype=tuple->fields[0].value;if(subtype==6){const Node *pair=tuple->children.size()==1?all[i].at(tuple->children[0]):nullptr;if(!pair||pair->fields.size()!=2||pair->fields[0].value!=0x79f0)continue;}else if(subtype!=8&&subtype!=13&&!(n.opcode==0x41&&subtype==12)&&!(extended&&subtype==4))continue;
  std::vector<uint8_t> state(352,0xff);if(!runtime.start(Cursor(uint16_t(57+i),n.offset),state,error))return 3;RuntimeStatus status=runtime.run();
  if(subtype==6){uint16_t value=0;if(status!=kRuntimePassFinished||!runtime.progressionSection(value))return 4;std::printf("action\t%u\t%u\t%u\tsection\t%u\n",57+i,n.offset,subtype,unsigned(value));}
  else if(subtype==12){if(status!=kRuntimePassFinished)return 4;std::printf("action\t%u\t%u\t%u\treset\t%u\t%u\n",57+i,n.offset,subtype,unsigned(runtime.packed()[53]),unsigned(std::count(runtime.packed().begin()+54,runtime.packed().end(),0)));}
  else{if(status!=kRuntimeWaiting||runtime.requests().size()!=1)return 4;const RuntimeRequest& request=runtime.requests()[0];std::printf("action\t%u\t%u\t%u\t%u\t%u\t%u\t%u",57+i,n.offset,subtype,unsigned(request.kind),request.queue,request.first,request.second);for(uint16_t value:request.operands)std::printf("\t%u",value);std::printf("\n");}++count;
 }
 std::printf("native_action_corpus=%u\n",count);return 0;
}
int runNativeQueryCorpus(const std::string& folder){
 using namespace Snatcher;std::vector<Scenario> all;std::string error;for(unsigned i=0;i<39;++i){char file[32];std::snprintf(file,sizeof(file),"/SP%02u.BIN",i);std::ifstream input((folder+file).c_str(),std::ios::binary);std::vector<uint8_t> data((std::istreambuf_iterator<char>(input)),std::istreambuf_iterator<char>());Scenario source;if(!parseScenario(data.data(),data.size(),source,error))return 2;all.push_back(source);}
 EventScheduler events;SemanticTrace trace;trace.enable(true);NarrativeRuntime runtime(all,events,trace);TestQueries queries;runtime.setQuerySource(&queries);unsigned count=0;
 for(unsigned i=0;i<39;++i)for(const Node& node:all[i].nodes){const Node* tuple=node.opcode==0x42&&node.children.size()==1?all[i].at(node.children[0]):nullptr;if(!tuple||tuple->opcode!=0x23||tuple->fields.size()!=2||tuple->fields[0].value!=5)continue;queries.calls.clear();if(!runtime.start(Cursor(uint16_t(57+i),node.offset),std::vector<uint8_t>(352,0),error)||runtime.run()!=kRuntimePassFinished||queries.calls.size()!=1)return 3;NarrativeQuery expected;if(!decodeNarrativeQuery(tuple->fields[1].value,expected)||queries.calls[0]!=expected)return 4;std::printf("query\t%u\t%u\t%u\t%u\n",57+i,node.offset,unsigned(expected),0x8100+unsigned(expected));++count;}
 std::printf("native_query_corpus=%u\n",count);return count==163?0:5;
}
